// E-books without external programs (EPUB, MOBI, FB2, HTMLZ, TXTZ, comics) and with the optional calibre package.
// Inputs are generated by EbookBuilders; outputs are parsed back (EPUB structure, PDF page counts, text content).

using System.IO.Compression;
using System.Text;
using System.Xml.Linq;
using Filee.Core.Conversion;
using Filee.Core.Presets;
using Filee.Engines.Ebooks;
using ImageMagick;
using PdfSharp.Pdf.IO;

namespace Filee.Engines.Tests;

public class EbookTests(EngineFixture fx) : IClassFixture<EngineFixture>
{
    private static readonly string[] OptionalEngines = ["pandoc", "libreoffice", "calibre"];

    private RoutePlanner BuiltInPlanner(params string[] assumeInstalled) =>
        new ConverterCatalog(fx.Converters.Where(c => !OptionalEngines.Contains(c.Id))) { Priority = fx.Catalog.Priority }
            .CreatePlanner(assumeInstalled);

    private async Task<string> ConvertAsync(string input, string target, Preset? preset = null)
    {
        preset ??= new Preset();
        preset.TargetFormat = target;
        var job = await fx.ConvertAsync([input], preset);
        Assert.True(job.State == JobState.Completed, string.Join("; ", job.Files.Select(f => $"{f.ErrorKey} {f.ErrorDetail}")));
        return job.Outputs.Single();
    }

    private async Task<string> FailureAsync(string input, string target)
    {
        var job = await fx.ConvertAsync([input], new Preset { TargetFormat = target });
        Assert.Equal(JobState.Failed, job.State);
        return job.Files.Single().ErrorDetail ?? "";
    }

    private bool HasRhwp => fx.Catalog.StatusOf(fx.Converters.Single(c => c.Id == "rhwp")).IsAvailable;

    private bool HasCalibre => fx.Catalog.StatusOf(fx.Converters.Single(c => c.Id == "calibre")).IsAvailable;

    private static int PdfPages(string pdf)
    {
        using var document = PdfReader.Open(pdf, PdfDocumentOpenMode.Import);
        return document.PageCount;
    }

    /// <summary>The text of an EPUB read back with the built-in reader.</summary>
    private string EpubText(string epub) =>
        Hwp.Hwpx.PlainTextWriter.Write(EpubReader.ReadBook(epub, fx.NewFolder(), TestContext.Current.CancellationToken).Document);

    // ───────────────────────── Routes ─────────────────────────

    [Fact]
    public void E_book_routes_use_the_built_in_engine()
    {
        var planner = BuiltInPlanner("rhwp");

        // E-book readers are also registered with the HWPX writer, which comes first in the default engine order.
        Assert.Equal(["hwpx-writer", "rhwp"], planner.Plan("epub", "pdf")!.Steps.Select(s => s.Converter.Id));
        Assert.Equal(["hwpx-writer", "rhwp", "pdfium"], planner.Plan("mobi", "png")!.Steps.Select(s => s.Converter.Id));
        foreach (var (from, to) in new[] { ("mobi", "epub"), ("azw3", "epub"), ("fb2", "epub"), ("epub", "fb2"), ("md", "epub"), ("docx", "epub"), ("epub", "txt"), ("cbr", "pdf"), ("pdf", "cbz"), ("azw4", "pdf"), ("htmlz", "txtz") })
            Assert.Equal("ebook", Assert.Single(planner.Plan(from, to)!.Steps).Converter.Id);
        Assert.Null(planner.Plan("epub", "mobi")); // needs calibre
    }

    [Fact]
    public void Calibre_adds_kindle_output_and_rare_formats_but_never_wins_over_built_in_routes()
    {
        var planner = fx.Catalog.CreatePlanner(["calibre"]);

        Assert.Equal("calibre", Assert.Single(planner.Plan("epub", "azw3")!.Steps).Converter.Id);
        Assert.Equal(["ebook", "calibre"], planner.Plan("fb2", "mobi")!.Steps.Select(s => s.Converter.Id));
        Assert.Equal(["calibre", "ebook"], planner.Plan("lit", "txt")!.Steps.Select(s => s.Converter.Id));
        Assert.Equal("ebook", Assert.Single(planner.Plan("mobi", "epub")!.Steps).Converter.Id);
        Assert.Equal("ebook", Assert.Single(planner.Plan("epub", "fb2")!.Steps).Converter.Id);
    }

    // ───────────────────────── EPUB ─────────────────────────

    [Fact]
    public void Epub_reader_keeps_chapters_links_pictures_and_metadata()
    {
        var book = EpubReader.ReadBook(EbookBuilders.Epub(fx.NewFolder()), fx.NewFolder(), TestContext.Current.CancellationToken);

        Assert.Equal("별빛 이야기", book.Metadata.Title);
        Assert.Equal(["김작가"], book.Metadata.Authors);
        Assert.Equal("ko", book.Metadata.Language);
        Assert.EndsWith("cover.png", book.Metadata.CoverImage);
        var blocks = book.Document.Sections.Single().Blocks;
        var headings = blocks.OfType<Hwp.Hwpx.HParagraph>().Where(p => p.HeadingLevel == 1).ToList();
        Assert.Equal(["첫 번째 장", "두 번째 장", "세 번째 장"], headings.Select(h => Hwp.Hwpx.HDocumentWalker.Text(h.Inlines)));
        Assert.Equal([false, true, true], headings.Select(h => h.PageBreakBefore)); // every chapter on a new page
        var inlines = blocks.SelectMany(b => Hwp.Hwpx.HDocumentWalker.Inlines([b])).ToList();
        var link = inlines.OfType<Hwp.Hwpx.HLink>().Single();
        Assert.Contains(inlines.OfType<Hwp.Hwpx.HBookmark>(), b => "#" + b.Name == link.Target); // chapter 1 → note in "ch 3.xhtml"
        Assert.Single(inlines.OfType<Hwp.Hwpx.HImage>());
        Assert.Single(blocks.OfType<Hwp.Hwpx.HTable>());
        Assert.Contains(inlines.OfType<Hwp.Hwpx.HText>(), t => t.Text == "크게" && t.Format.Bold is true); // class rule from the linked CSS
        Assert.Contains(inlines.OfType<Hwp.Hwpx.HText>(), t => t.Text == "빈 div 다음 문단"); // <div/> did not swallow the page
    }

    [Fact]
    public async Task Epub_to_pdf_puts_every_chapter_on_its_own_page()
    {
        Assert.SkipUnless(HasRhwp, "rhwp not found (pwsh build/fetch-engines.ps1 -Only rhwp)");
        var pdf = await ConvertAsync(EbookBuilders.Epub(fx.NewFolder()), "pdf");

        Assert.True(PdfPages(pdf) >= 3);
    }

    [Fact]
    public async Task Epub_to_txt_html_and_markdown()
    {
        var epub = EbookBuilders.Epub(fx.NewFolder());

        var text = await File.ReadAllTextAsync(await ConvertAsync(epub, "txt"), TestContext.Current.CancellationToken);
        foreach (var expected in new[] { "첫 번째 장", "밤하늘에 별이 반짝였다.", "주석 내용입니다.", "● 목록 하나", "이름\t값" })
            Assert.Contains(expected, text);
        Assert.DoesNotContain("<", text);

        var html = await File.ReadAllTextAsync(await ConvertAsync(epub, "html"), TestContext.Current.CancellationToken);
        Assert.Contains("<h1 id=\"_h1\">첫 번째 장</h1>", html);
        Assert.Contains("src=\"data:image/png;base64,", html); // one self-contained file
        Assert.Contains("<b>별</b>", html);
        Assert.Contains("<title>별빛 이야기</title>", html);

        var md = await ConvertAsync(epub, "md");
        var markdown = await File.ReadAllTextAsync(md, TestContext.Current.CancellationToken);
        Assert.Contains("# 첫 번째 장", markdown);
        Assert.Contains("**별**", markdown);
        Assert.Contains("| 이름 | 값 |", markdown);
        var picture = System.Text.RegularExpressions.Regex.Match(markdown, @"!\[\]\(<([^>]+)>\)").Groups[1].Value;
        Assert.True(File.Exists(Path.Combine(Path.GetDirectoryName(md)!, Uri.UnescapeDataString(picture))));
    }

    [Fact]
    public async Task Markdown_to_epub_is_a_valid_package_that_reads_back()
    {
        var dir = fx.NewFolder();
        File.WriteAllBytes(Path.Combine(dir, "그림.png"), EbookBuilders.Png(120, 80, MagickColors.Gold));
        var md = Path.Combine(dir, "책.md");
        await File.WriteAllTextAsync(md, """
            ---
            title: 마크다운 책
            ---

            # 1장 시작

            첫 문단에 **굵게**와 [링크](https://example.com)가 있습니다.[^1]

            ![그림](그림.png)

            ## 1.1 절

            - 하나
            - 둘

            # 2장 끝

            | A | B |
            |---|---|
            | 1 | 2 |

            [^1]: 각주입니다.
            """, TestContext.Current.CancellationToken);

        var epub = await ConvertAsync(md, "epub");

        var package = EpubAssert.Valid(epub);
        Assert.Equal("마크다운 책", package.Title);
        Assert.Equal("ko", package.Language);
        Assert.Equal(2, package.Chapters); // split at the level-1 headings
        Assert.Equal(1, package.Images);
        Assert.Contains("1장 시작", package.Toc);
        Assert.Contains("1.1 절", package.Toc);
        var text = EpubText(epub);
        foreach (var expected in new[] { "1장 시작", "굵게", "하나", "2장 끝", "각주입니다." })
            Assert.Contains(expected, text);
    }

    [Fact]
    public async Task Text_html_and_docx_become_epub()
    {
        var dir = fx.NewFolder();
        var txt = Path.Combine(dir, "메모.txt");
        await File.WriteAllTextAsync(txt, "첫 문단의 첫 줄\n같은 문단\n\n둘째 문단", TestContext.Current.CancellationToken);
        var html = Path.Combine(dir, "page.html");
