    [Fact]
    public async Task Drm_protected_epub_is_refused_with_a_clear_message()
    {
        var dir = fx.NewFolder();
        var epub = EbookBuilders.Epub(dir);
        using (var zip = ZipFile.Open(epub, ZipArchiveMode.Update))
            EbookBuilders.Entry(zip, "META-INF/encryption.xml", """
                <encryption xmlns="urn:oasis:names:tc:opendocument:xmlns:container" xmlns:enc="http://www.w3.org/2001/04/xmlenc#">
                  <enc:EncryptedData><enc:EncryptionMethod Algorithm="http://www.w3.org/2001/04/xmlenc#aes128-cbc"/>
                  <enc:CipherData><enc:CipherReference URI="OEBPS/Text/ch1.xhtml"/></enc:CipherData></enc:EncryptedData>
                </encryption>
                """);

        Assert.Contains("DRM", await FailureAsync(epub, "txt"));
    }

    // ───────────────────────── MOBI ─────────────────────────

    private const string MobiHtml = """
        <html><head><guide><reference type="toc" title="Contents" filepos=0000000000 /></guide></head><body>
        <h1>Chapter One</h1>
        <p>It was a <b>dark</b> and stormy night; the rain fell in torrents — except at occasional intervals.</p>
        <p>See <a filepos=FILEPOS>the note</a> below. Ünïcödé text and 한글 too.</p>
        <p><img recindex="00001" /></p>
        <mbp:pagebreak/>
        <h1>Chapter Two</h1>
        <p>The note is here.</p>
        </body></html>
        """;

    /// <summary>MOBI HTML with a filepos link pointing at "The note is here." (a byte offset in the text).</summary>
    private static string MobiSource()
    {
        var placeholder = MobiHtml.Replace("FILEPOS", "0000000000", StringComparison.Ordinal);
        var target = Encoding.UTF8.GetBytes(placeholder[..placeholder.IndexOf("<p>The note", StringComparison.Ordinal)]).Length;
        return MobiHtml.Replace("FILEPOS", target.ToString("0000000000", System.Globalization.CultureInfo.InvariantCulture), StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(2)] // PalmDOC
    [InlineData(17480)] // HUFF/CDIC
    [InlineData(1)] // uncompressed
    public async Task Mobi_to_epub_keeps_text_pictures_links_and_metadata(int compression)
    {
        var dir = fx.NewFolder();
        var mobi = Path.Combine(dir, "book.mobi");
        var cover = EbookBuilders.Png(100, 150, MagickColors.DarkBlue);
        await File.WriteAllBytesAsync(mobi, EbookBuilders.Mobi(MobiSource(), [EbookBuilders.Png(64, 32, MagickColors.Orange), cover],
            new EbookBuilders.MobiOptions(Compression: compression, Cover: 1, Title: "Stormy Night", Author: "E. Bulwer-Lytton")), TestContext.Current.CancellationToken);

        var epub = await ConvertAsync(mobi, "epub");

        var package = EpubAssert.Valid(epub);
        Assert.Equal("Stormy Night", package.Title);
        Assert.Contains("E. Bulwer-Lytton", package.Authors);
        Assert.Equal(2, package.Images); // the picture and the cover
        Assert.True(package.HasCover);
        var book = EpubReader.ReadBook(epub, fx.NewFolder(), TestContext.Current.CancellationToken);
        var text = Hwp.Hwpx.PlainTextWriter.Write(book.Document);
        foreach (var expected in new[] { "Chapter One", "dark and stormy night", "Ünïcödé text and 한글 too", "Chapter Two", "The note is here." })
            Assert.Contains(expected, text);
        var inlines = book.Document.Sections.SelectMany(s => Hwp.Hwpx.HDocumentWalker.Inlines(s.Blocks)).ToList();
        var link = inlines.OfType<Hwp.Hwpx.HLink>().Single();
        Assert.Contains(inlines.OfType<Hwp.Hwpx.HBookmark>(), b => "#" + b.Name == link.Target); // filepos link survives
        Assert.True(inlines.OfType<Hwp.Hwpx.HText>().Single(t => t.Text == "dark").Format.Bold);
    }

