    [Fact]
    public async Task Palmdoc_text_books_are_read_as_text()
    {
        var text = "Plain PalmDOC text.\n\nSecond paragraph of the book."u8.ToArray();
        var record0 = new byte[16];
        record0[1] = 2; // PalmDOC compression
        System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(record0.AsSpan(4), (uint)text.Length);
        record0[9] = 1; // one text record
        var prc = Path.Combine(fx.NewFolder(), "old.prc");
        await File.WriteAllBytesAsync(prc, EbookBuilders.PalmDb("Old Book", "TEXtREAd", [record0, EbookBuilders.PalmDocCompress(text)]), TestContext.Current.CancellationToken);

        var txt = await File.ReadAllTextAsync(await ConvertAsync(prc, "txt"), TestContext.Current.CancellationToken);

        Assert.Contains("Plain PalmDOC text.", txt);
        Assert.Contains("Second paragraph of the book.", txt);
    }

