/// <summary>EPUB structure checks (the OCF / OPF rules epubcheck applies first).</summary>
internal static class EpubAssert
{
    /// <summary>A package path relative to a folder of the package ("OEBPS/Text" + "../Images/a.png").</summary>
    private static string Combine(string folder, string relative)
    {
        var parts = folder.Split('/', StringSplitOptions.RemoveEmptyEntries).ToList();
        foreach (var part in relative.Split('/'))
        {
            if (part == "..")
            {
                if (parts.Count > 0)
                    parts.RemoveAt(parts.Count - 1);
            }
            else if (part is not ("." or ""))
            {
                parts.Add(part);
            }
        }
        return string.Join('/', parts);
    }

    public sealed record Package(string Title, string Language, List<string> Authors, int Chapters, int Images, bool HasCover, bool FixedLayout, string Toc, string AllText);

    public static Package Valid(string epub)
    {
        // "mimetype" is the first entry, stored, without extra field, so its content is at byte 38.
        var bytes = File.ReadAllBytes(epub);
        Assert.Equal("PK\u0003\u0004", Encoding.ASCII.GetString(bytes, 0, 4));
        Assert.Equal(0, BitConverter.ToUInt16(bytes, 8)); // stored
        Assert.Equal(0, BitConverter.ToUInt16(bytes, 28)); // no extra field
        Assert.Equal("mimetypeapplication/epub+zip", Encoding.ASCII.GetString(bytes, 30, 28));

        using var zip = ZipFile.OpenRead(epub);
        var container = XDocument.Load(zip.GetEntry("META-INF/container.xml")!.Open());
        var opfPath = container.Descendants().Single(e => e.Name.LocalName == "rootfile").Attribute("full-path")!.Value;
        var opf = XDocument.Load(zip.GetEntry(opfPath)!.Open());
        var root = Path.GetDirectoryName(opfPath)!.Replace('\\', '/');
        string Resolve(string href) => (root.Length > 0 ? root + "/" : "") + Uri.UnescapeDataString(href);

        XNamespace opfNs = "http://www.idpf.org/2007/opf";
        XNamespace dc = "http://purl.org/dc/elements/1.1/";
        Assert.Equal("3.0", opf.Root!.Attribute("version")!.Value);
        var items = opf.Descendants(opfNs + "item").ToList();
        foreach (var item in items)
            Assert.NotNull(zip.GetEntry(Resolve(item.Attribute("href")!.Value))); // every manifest item exists
        Assert.Equal(items.Count, items.Select(i => i.Attribute("id")!.Value).Distinct().Count());
        var ids = items.ToDictionary(i => i.Attribute("id")!.Value);
        var spine = opf.Descendants(opfNs + "itemref").Select(r => ids[r.Attribute("idref")!.Value]).ToList();
        Assert.NotEmpty(spine);
        Assert.NotNull(opf.Descendants(dc + "identifier").SingleOrDefault());
        Assert.NotNull(opf.Descendants(opfNs + "meta").SingleOrDefault(m => m.Attribute("property")?.Value == "dcterms:modified"));

        // Navigation: the nav document (with a non-empty toc) and the NCX, both well-formed.
        var nav = items.Single(i => (i.Attribute("properties")?.Value ?? "").Split(' ').Contains("nav"));
        var navXml = XDocument.Load(zip.GetEntry(Resolve(nav.Attribute("href")!.Value))!.Open());
        Assert.Contains(navXml.Descendants(), e => e.Name.LocalName == "li");
        var ncx = items.Single(i => i.Attribute("media-type")!.Value == "application/x-dtbncx+xml");
        var ncxXml = XDocument.Load(zip.GetEntry(Resolve(ncx.Attribute("href")!.Value))!.Open());
        Assert.Contains(ncxXml.Descendants(), e => e.Name.LocalName == "navPoint");

        // Every XHTML file is well-formed and its links and pictures point at files in the package.
        var allText = new StringBuilder();
        foreach (var item in items.Where(i => i.Attribute("media-type")!.Value == "application/xhtml+xml"))
        {
            var path = Resolve(item.Attribute("href")!.Value);
            var xhtml = XDocument.Load(zip.GetEntry(path)!.Open());
            allText.Append(xhtml.ToString());
            var folder = Path.GetDirectoryName(path)!.Replace('\\', '/');
            foreach (var reference in xhtml.Descendants().SelectMany(e => e.Attributes().Where(a => a.Name.LocalName is "src" or "href")))
            {
                var value = reference.Value.Split('#')[0];
                if (value.Length == 0 || value.Contains(':', StringComparison.Ordinal))
                    continue;
                var target = Combine(folder, Uri.UnescapeDataString(value));
                Assert.True(zip.GetEntry(target) is not null, $"{path} refers to {value}, which is not in the package.");
            }
        }

        return new Package(
            opf.Descendants(dc + "title").First().Value,
            opf.Descendants(dc + "language").First().Value,
            [.. opf.Descendants(dc + "creator").Select(c => c.Value)],
            spine.Count(s => !s.Attribute("href")!.Value.StartsWith("cover", StringComparison.Ordinal)),
            items.Count(i => i.Attribute("media-type")!.Value.StartsWith("image/", StringComparison.Ordinal)),
            items.Any(i => (i.Attribute("properties")?.Value ?? "").Contains("cover-image", StringComparison.Ordinal)),
            opf.Descendants(opfNs + "meta").Any(m => m.Attribute("property")?.Value == "rendition:layout" && m.Value == "pre-paginated"),
            navXml.ToString(),
            allText.ToString());
    }
}
